import type { BankQuestion } from "@/lib/bank";

/** Synonyms, Antonyms and One-Word Substitution (English): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eng-vocabulary-1","question":"Choose the synonym of “Abundant”.","options":["Insufficient","Plentiful","Abandoned","Meagre"],"answer":1,"explanation":"Abundant means existing in large quantities, i.e. plentiful. Abandoned is a look-alike trap, while insufficient and meagre are near-opposites.","difficulty":"easy"},
  {"id":"eng-vocabulary-2","question":"Choose the antonym of “Ancient”.","options":["Old","Modern","Antique","Historic"],"answer":1,"explanation":"Ancient means belonging to the very distant past, so its opposite is modern (of the present day). Old, antique and historic all point the same way as ancient; the trap is picking a word merely related to age.","difficulty":"easy"},
  {"id":"eng-vocabulary-3","question":"Choose the antonym of “Benevolent”.","options":["Kind","Generous","Malevolent","Charitable"],"answer":2,"explanation":"Benevolent means well-meaning; malevolent means wishing harm.","difficulty":"moderate"},
  {"id":"eng-vocabulary-4","question":"One who knows everything is called:","options":["Omnipotent","Omnipresent","Omniscient","Omnivorous"],"answer":2,"explanation":"Omniscient = all-knowing; omnipotent = all-powerful; omnipresent = present everywhere.","difficulty":"moderate"},
  {"id":"eng-vocabulary-5","question":"One who looks at the bright side of things is called:","options":["Pessimist","Optimist","Realist","Altruist"],"answer":1,"explanation":"An optimist expects the best; a pessimist expects the worst.","difficulty":"moderate"},
  {"id":"eng-vocabulary-6","question":"Choose the synonym of “Ephemeral”.","options":["Everlasting","Short-lived","Ethereal","Superficial"],"answer":1,"explanation":"Ephemeral (from Greek 'lasting a day') means lasting a very short time, so short-lived fits. Ethereal is a sound-alike meaning light and delicate, and everlasting is the opposite.","difficulty":"hard"},
  {"id":"eng-vocabulary-7","question":"A person who can speak many languages is called a:","options":["Linguist","Polyglot","Orator","Philologist"],"answer":1,"explanation":"A polyglot knows and uses several languages; a linguist studies language scientifically.","difficulty":"hard"},
  {"id":"eng-vocabulary-8","question":"Choose the antonym of “Verbose”.","options":["Talkative","Concise","Lengthy","Loud"],"answer":1,"explanation":"Verbose means using more words than needed; concise means brief and to the point.","difficulty":"hard"},
  {"id":"eng-vocabulary-9","question":"Choose the synonym of “Obsequious”.","options":["Arrogant","Servile","Honest","Lazy"],"answer":1,"explanation":"Obsequious means excessively eager to please or obey, i.e., servile.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-10","question":"A government by the wealthy is called:","options":["Oligarchy","Plutocracy","Theocracy","Gerontocracy"],"answer":1,"explanation":"Plutocracy (Greek ploutos = wealth) is rule by the rich. Oligarchy is rule by a few, whoever they are, which is the usual trap; theocracy is rule by religious leaders and gerontocracy rule by the elderly.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-11","question":"Choose the antonym of “Garrulous”.","options":["Talkative","Taciturn","Friendly","Angry"],"answer":1,"explanation":"Garrulous means excessively talkative; taciturn means reserved and saying little.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-12","question":"Choose the antonym of “Abundant”.","options":["Plentiful","Scarce","Ample","Rich"],"answer":1,"explanation":"Abundant means existing in large quantities, so scarce (in short supply) is its opposite. Plentiful, ample and rich all mean the same as abundant; the trap is ticking a synonym in an antonym question.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"eng-vocabulary-13","question":"Choose the synonym of “Candid”.","options":["Secretive","Frank","Clever","Rude"],"answer":1,"explanation":"Candid means frank and open in saying what one thinks. Rude is the tempting trap: candour can sound blunt, but candid describes honesty, not bad manners, and secretive is its opposite.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-14","question":"One word for “a person who can speak many languages”:","options":["Linguist","Polyglot","Orator","Bilingual"],"answer":1,"explanation":"A polyglot knows several languages; a linguist studies language.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-15","question":"The idiom “to beat around the bush” means:","options":["To hunt for game in a forest","To avoid the main point","To work very hard without rest","To lose one’s way in the woods"],"answer":1,"explanation":"To beat around the bush is to talk indirectly and avoid the real issue (beaters struck the bushes instead of going for the game itself). The literal readings about hunting or forests are the traps.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-16","question":"Choose the antonym of “Ephemeral”.","options":["Brief","Eternal","Fleeting","Momentary"],"answer":1,"explanation":"Ephemeral means lasting a very short time, so eternal is its opposite. Brief, fleeting and momentary are all synonyms of ephemeral, which is the trap in an antonym question.","difficulty":"hard","source":"SSC CGL · SBI PO"},
  {"id":"eng-vocabulary-17","question":"One word for “a government by the rich”:","options":["Oligarchy","Plutocracy","Gerontocracy","Theocracy"],"answer":1,"explanation":"Plutocracy (Greek ploutos = wealth) is rule by the wealthy. Oligarchy is rule by a few, whether rich or not, which is the common trap; gerontocracy is rule by the elderly and theocracy rule by priests.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-18","question":"Choose the synonym of “Ubiquitous”.","options":["Infrequent","Omnipresent","Inconspicuous","Iniquitous"],"answer":1,"explanation":"Ubiquitous means present or found everywhere, i.e. omnipresent. Iniquitous (wicked) is a sound-alike trap, and infrequent is close to the opposite.","difficulty":"hard"},
  {"id":"eng-vocabulary-19","question":"Choose the antonym of “Laconic”.","options":["Succinct","Verbose","Terse","Lackadaisical"],"answer":1,"explanation":"Laconic means using very few words; verbose is the opposite. Succinct and terse are synonyms, and lackadaisical (lazy, careless) is only a look-alike.","difficulty":"hard"},
  {"id":"eng-vocabulary-20","question":"One word for “a person who bears pain or hardship without showing feelings”:","options":["Stoic","Hedonist","Cynic","Sceptic"],"answer":0,"explanation":"A stoic endures without complaint; a hedonist seeks pleasure.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-21","question":"The idiom “to cut the Gordian knot” means:","options":["To break a solemn promise made to a close friend","To solve a hard problem by bold, direct action","To end a long friendship over a small quarrel","To waste time untangling small, minor details"],"answer":1,"explanation":"From the legend of Alexander slicing through a knot nobody could untie.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-22","question":"Choose the synonym of “Obfuscate”.","options":["Clarify","Obscure","Illuminate","Simplify"],"answer":1,"explanation":"To obfuscate is to make something deliberately unclear or confusing, so obscure is the synonym. Clarify, illuminate and simplify all mean the opposite.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-23","question":"Choose the antonym of “Recalcitrant”.","options":["Obstinate","Compliant","Defiant","Unruly"],"answer":1,"explanation":"Recalcitrant means stubbornly disobedient; compliant is the opposite.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-24","question":"Choose the word nearest in meaning to OBSEQUIOUS.","options":["Servile","Obstinate","Obscure","Generous"],"answer":0,"explanation":"Obsequious means excessively eager to please or obey, i.e. servile or fawning. Obstinate and obscure are sound-alike traps, and generous confuses eagerness to please with kindness.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-25","question":"Choose the word opposite in meaning to EPHEMERAL.","options":["Transient","Perpetual","Fleeting","Brief"],"answer":1,"explanation":"Ephemeral means short-lived; the other three options are its synonyms.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-26","question":"One word for “a person who is indifferent to pleasure and pain”:","options":["Stoic","Hedonist","Cynic","Epicure"],"answer":0,"explanation":"A stoic endures pain and pleasure without showing feeling; a hedonist pursues pleasure.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-27","question":"Choose the word nearest in meaning to PERFUNCTORY.","options":["Cursory","Thorough","Deliberate","Elaborate"],"answer":0,"explanation":"Perfunctory means done quickly and without real care or interest, i.e. cursory; the other three describe careful work.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-28","question":"Choose the word opposite in meaning to PARSIMONIOUS.","options":["Penny-pinching","Munificent","Thrifty","Miserly"],"answer":1,"explanation":"Parsimonious means unwilling to spend money; munificent means very generous, the opposite. Penny-pinching, thrifty and miserly are all near-synonyms of the given word.","difficulty":"very-hard","source":"SSC CGL · SBI PO"},
  {"id":"eng-vocabulary-29","question":"Choose the synonym of “Brave”.","options":["Courageous","Faint-hearted","Cowardly","Timorous"],"answer":0,"explanation":"Brave means showing courage; courageous is its synonym, while faint-hearted, cowardly and timorous are its opposites.","difficulty":"easy","source":"SSC GD · RRB Group D"},
  {"id":"eng-vocabulary-30","question":"Choose the antonym of “Generous”.","options":["Kind","Liberal","Stingy","Charitable"],"answer":2,"explanation":"Generous means giving freely; stingy (mean, unwilling to spend) is the opposite. Liberal and charitable are synonyms.","difficulty":"easy","source":"SSC GD · SSC CHSL"},
  {"id":"eng-vocabulary-31","question":"One word for “a place where bees are kept”:","options":["Aviary","Aquarium","Arboretum","Apiary"],"answer":3,"explanation":"An apiary is where bees (Latin apis) are kept. An aviary houses birds, an aquarium fish and an arboretum trees.","difficulty":"easy","source":"SSC CHSL · SSC CGL"},
  {"id":"eng-vocabulary-32","question":"Choose the synonym of “Meticulous”.","options":["Scrupulous","Slapdash","Careless","Superficial"],"answer":0,"explanation":"Meticulous means very careful and precise about details; scrupulous is the closest. Careless, slapdash and superficial all describe the opposite kind of work.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-33","question":"Choose the antonym of “Transparent”.","options":["Clear","Opaque","Lucid","Obvious"],"answer":1,"explanation":"Transparent means allowing light through or easy to see through; opaque means not letting light pass. Clear and lucid are synonyms.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eng-vocabulary-34","question":"One word for “a person who is unable to pay his debts”:","options":["Insolvent","Solvent","Moneylender","Debtor"],"answer":0,"explanation":"Insolvent is the person or firm unable to pay debts. A debtor merely owes money and may well be able to pay; a moneylender is owed money, and solvent is the opposite.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-35","question":"The idiom “to bury the hatchet” means:","options":["To hide a weapon","To start a quarrel","To make peace","To dig a grave"],"answer":2,"explanation":"To bury the hatchet is to end a quarrel and become friendly again; the literal picture of burying a weapon is the trap.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-36","question":"One word for “the study of ancient remains and societies”:","options":["Anthropology","Geology","Palaeontology","Archaeology"],"answer":3,"explanation":"Archaeology studies ancient societies through their physical remains. Anthropology studies humankind generally, palaeontology fossils, geology the earth.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eng-vocabulary-37","question":"Choose the synonym of “Lethargic”.","options":["Energetic","Sluggish","Alert","Agile"],"answer":1,"explanation":"Lethargic means lacking energy or enthusiasm; sluggish is its synonym. The other three options all describe liveliness.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-38","question":"Choose the synonym of “Taciturn”.","options":["Reserved","Talkative","Gloomy","Rude"],"answer":0,"explanation":"Taciturn means habitually saying little; reserved is nearest. Talkative is the antonym, and gloomy or rude describe mood, not speech.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-39","question":"Choose the antonym of “Prodigal”.","options":["Frugal","Lavish","Wasteful","Reckless"],"answer":0,"explanation":"Prodigal means wastefully extravagant (as in the prodigal son); frugal, careful with money, is the opposite. Lavish and wasteful are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-40","question":"One word for “a person who hates mankind”:","options":["Philanthropist","Misogynist","Anthropologist","Misanthrope"],"answer":3,"explanation":"A misanthrope hates people in general. A misogynist hates women specifically, a philanthropist loves mankind and an anthropologist studies it.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-41","question":"The idiom “a wild goose chase” means:","options":["A hunting expedition","A futile search","A sudden journey","A noisy quarrel"],"answer":1,"explanation":"A wild goose chase is a hopeless, pointless pursuit of something that cannot be found.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-42","question":"Choose the word nearest in meaning to SANGUINE.","options":["Bloody","Pessimistic","Optimistic","Calm"],"answer":2,"explanation":"Sanguine means hopeful and confident about the future. Though it comes from the Latin for blood, 'bloody' is the etymological trap, not the meaning.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-43","question":"Choose the word opposite in meaning to OBSOLETE.","options":["Ancient","Current","Dormant","Outdated"],"answer":1,"explanation":"Obsolete means no longer in use or out of date; current (in present use) is the opposite. Outdated is a synonym.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-44","question":"One word for “a person who cannot be corrected or reformed”:","options":["Irreconcilable","Indelible","Incorrigible","Infallible"],"answer":2,"explanation":"Incorrigible means beyond correction or reform. Irreconcilable describes people or views that cannot be brought into agreement, indelible means cannot be erased and infallible means never wrong.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-45","question":"Fill in the blank with the most suitable word: The minister's ___ remarks about the flood victims drew sharp criticism.","options":["callus","candid","careful","callous"],"answer":3,"explanation":"Callous means insensitive and unfeeling, which is why the remarks were criticised. Callus (a patch of hard skin) is the homophone trap; candid or careful remarks would not invite criticism.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-46","question":"Choose the word nearest in meaning to EQUIVOCAL.","options":["Ambiguous","Equitable","Unequivocal","Forthright"],"answer":0,"explanation":"Equivocal means open to more than one interpretation, deliberately vague. Equitable (fair) is a look-alike trap, while unequivocal and forthright mean the opposite.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-47","question":"Choose the word nearest in meaning to PUSILLANIMOUS.","options":["Generous","Insignificant","Cowardly","Cheerful"],"answer":2,"explanation":"Pusillanimous means lacking courage, timid. The word's length tempts guesses like 'insignificant'; its root is Latin pusillus (very small) + animus (spirit).","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-48","question":"Choose the word opposite in meaning to NADIR.","options":["Bottom","Zenith","Depth","Abyss"],"answer":1,"explanation":"Nadir is the lowest point; zenith is the highest. The other three are synonyms of nadir, not antonyms.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-49","question":"One word for “an irrational fear of enclosed spaces”:","options":["Claustrophobia","Agoraphobia","Acrophobia","Thalassophobia"],"answer":0,"explanation":"Claustrophobia is fear of confined spaces. Agoraphobia is fear of open or public places (the common confusion), acrophobia of heights and thalassophobia of the deep sea.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-50","question":"The idiom “to take something with a pinch of salt” means:","options":["To believe it fully and without question","To accept it, but with some scepticism","To add flavour or spice to a story","To criticise it harshly in public"],"answer":1,"explanation":"To take a statement with a pinch (or grain) of salt is to be sceptical about its truth, not to accept it wholesale.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-51","question":"Fill in the blank with the most suitable word: Despite his ___ manner, the professor was deeply respected by his students.","options":["affable","amiable","abrasive","agreeable"],"answer":2,"explanation":"'Despite' signals a contrast with being respected, so the manner must be unpleasant: abrasive (harsh, rude). Affable, amiable and agreeable all mean pleasant and would need 'because of', not 'despite'.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-52","question":"Choose the correctly spelt word to complete the sentence: The court's decision will have a ___ effect on future cases.","options":["salutory","salutary","salutery","saluatory"],"answer":1,"explanation":"Salutary (beneficial, though perhaps unwelcome) is spelt with -ary. The -ory ending is the usual misspelling by confusion with 'salutatory'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-53","question":"One word for “a person who believes that nothing can be known about the existence of God”:","options":["Atheist","Polytheist","Heretic","Agnostic"],"answer":3,"explanation":"An agnostic holds that God's existence cannot be known. An atheist positively denies God, a polytheist believes in many gods, and a heretic holds beliefs against accepted doctrine.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-54","question":"Which of the following pairs is NOT a pair of synonyms?","options":["Lucid – Clear","Candid – Frank","Docile – Stubborn","Mitigate – Alleviate"],"answer":2,"explanation":"Docile means easily taught or managed, the opposite of stubborn. Lucid/clear, candid/frank and mitigate/alleviate are all synonym pairs.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-55","question":"Choose the word opposite in meaning to AMELIORATE.","options":["Improve","Maintain","Worsen","Assist"],"answer":2,"explanation":"Ameliorate means to make better; worsen (aggravate) is its antonym. Improve is a synonym.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-56","question":"The idiom “to cut no ice” means:","options":["To fail to make any impression","To be extremely cold and unfriendly","To break a rule without being caught","To avoid a problem instead of facing it"],"answer":0,"explanation":"If an argument cuts no ice with someone, it has no effect on them. The literal reading about cold is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-57","question":"Choose the word nearest in meaning to VITUPERATIVE.","options":["Praising","Abusive","Lively","Vivid"],"answer":1,"explanation":"Vituperative means bitter and abusive in language. 'Lively' and 'vivid' are traps from the similar-looking root 'viv-'; praising is the opposite.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-58","question":"One word for “a disease that spreads across a whole country or the world”:","options":["Epidemic","Endemic","Sporadic","Pandemic"],"answer":3,"explanation":"A pandemic spreads over a whole country or the globe. An epidemic affects many people in one community at a time, an endemic disease is regularly found in a particular area, and sporadic means occurring occasionally.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"eng-vocabulary-59","question":"Choose the synonym of “Diligent”.","options":["Lackadaisical","Hardworking","Careless","Intelligent"],"answer":1,"explanation":"Diligent means showing steady, careful effort, i.e. hardworking. 'Intelligent' is about ability, not effort, while lackadaisical and careless are opposites.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"eng-vocabulary-60","question":"Choose the antonym of “Expand”.","options":["Contract","Enlarge","Proliferate","Explode"],"answer":0,"explanation":"Expand means to grow larger; contract means to become smaller. Enlarge and proliferate both describe growth, and explode is a violent expansion, not its opposite.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"eng-vocabulary-61","question":"Choose the synonym of “Prudent”.","options":["Reckless","Proud","Pretentious","Judicious"],"answer":3,"explanation":"Prudent means acting with care and good judgement, i.e. judicious. 'Proud' and 'pretentious' are look-alike traps; 'reckless' is the opposite.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-62", "question": "Choose the antonym of “Hostile”.", "options": ["Aggressive", "Unfriendly", "Amicable", "Belligerent"], "answer": 2, "explanation": "Hostile means unfriendly or antagonistic; amicable means friendly. Aggressive and belligerent are near-synonyms.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-63","question":"One word for “a person who walks in his sleep”:","options":["Insomniac","Somnambulist","Hypnotist","Somniloquist"],"answer":1,"explanation":"A somnambulist walks in sleep (Latin somnus = sleep, ambulare = walk). A somniloquist talks in sleep, the closest trap, and an insomniac cannot sleep at all.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-64","question":"The idiom “to burn the midnight oil” means:","options":["To work or study late into the night","To waste money on needless luxuries","To start a quarrel late at night","To finish one's work well before time"],"answer":0,"explanation":"To burn the midnight oil is to stay up late working or studying, originally by lamplight.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-65", "question": "One word for “writing that cannot be read”:", "options": ["Ineligible", "Illiterate", "Invisible", "Illegible"], "answer": 3, "explanation": "Illegible means not clear enough to be read. Ineligible (not qualified) is the classic look-alike trap.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-66", "question": "Choose the synonym of “Cajole”.", "options": ["Threaten", "Scold", "Coax", "Ignore"], "answer": 2, "explanation": "To cajole is to persuade someone by flattery or gentle urging, i.e. to coax. Threatening is the opposite approach.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-67","question":"Choose the antonym of “Ostentatious”.","options":["Grandiloquent","Unpretentious","Flamboyant","Pompous"],"answer":1,"explanation":"Ostentatious means showy and designed to impress; unpretentious means modest and simple. Grandiloquent, flamboyant and pompous all lean the same way as ostentatious.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-68", "question": "One word for “a speech made without preparation”:", "options": ["Extempore", "Soliloquy", "Monologue", "Epilogue"], "answer": 0, "explanation": "An extempore speech is delivered without preparation. A soliloquy is speaking one's thoughts alone on stage; an epilogue is a closing section.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-69","question":"The idiom “to be in the doldrums” means:","options":["To be in great danger at sea","To be very busy with routine work","To be deeply in debt to others","To be in low spirits or inactive"],"answer":3,"explanation":"The doldrums are calm equatorial waters where sailing ships stalled; being in the doldrums means feeling gloomy or stagnant.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id": "eng-vocabulary-70", "question": "Choose the synonym of “Alacrity”.", "options": ["Reluctance", "Anxiety", "Eagerness", "Laziness"], "answer": 2, "explanation": "Alacrity means brisk, cheerful readiness, i.e. eagerness. Reluctance is the opposite.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id":"eng-vocabulary-71","question":"Choose the antonym of “Indolent”.","options":["Lackadaisical","Industrious","Insolent","Sluggish"],"answer":1,"explanation":"Indolent means lazy; industrious means hardworking. 'Insolent' (rude) is a look-alike; lackadaisical and sluggish are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-72", "question": "One word for “the killing of one's own mother”:", "options": ["Matricide", "Patricide", "Fratricide", "Infanticide"], "answer": 0, "explanation": "Matricide (mater = mother) is killing one's mother. Patricide is killing the father, fratricide a brother, infanticide an infant.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-73", "question": "Choose the synonym of “Obdurate”.", "options": ["Obedient", "Obscure", "Remorseful", "Stubborn"], "answer": 3, "explanation": "Obdurate means stubbornly refusing to change one's opinion. 'Obedient' is the opposite, and 'obscure' only looks similar.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-74", "question": "Choose the antonym of “Truculent”.", "options": ["Aggressive", "Defiant", "Docile", "Belligerent"], "answer": 2, "explanation": "Truculent means eager to argue or fight; docile means meek and easily managed. The other three options are synonyms.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-75", "question": "One word for “an abnormal fear of water”:", "options": ["Acrophobia", "Hydrophobia", "Agoraphobia", "Xenophobia"], "answer": 1, "explanation": "Hydrophobia (hydro = water) is fear of water. Acrophobia is fear of heights, agoraphobia of open or crowded places, xenophobia of foreigners.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-76","question":"The phrase “a Pyrrhic victory” means:","options":["A victory won at such cost that it is almost a defeat","A victory won without a single battle being fought","A victory won through deceit rather than by fair means","A narrow victory snatched at the very last moment"],"answer":0,"explanation":"King Pyrrhus defeated Rome but lost so many men that the win was ruinous. A Pyrrhic victory costs the winner nearly as much as defeat.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id": "eng-vocabulary-77", "question": "Choose the synonym of “Sycophant”.", "options": ["Critic", "Rebel", "Sympathiser", "Flatterer"], "answer": 3, "explanation": "A sycophant is someone who flatters powerful people for personal gain. 'Sympathiser' is a look-alike trap.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-78", "question": "Choose the antonym of “Ebullient”.", "options": ["Exuberant", "Effervescent", "Subdued", "Buoyant"], "answer": 2, "explanation": "Ebullient means cheerful and full of energy; subdued means quiet and low-spirited. The other three are synonyms.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-79", "question": "Which of the following pairs is NOT a pair of antonyms?", "options": ["Arid – Humid", "Abate – Subside", "Benign – Malignant", "Lethal – Harmless"], "answer": 1, "explanation": "Abate and subside both mean to become less intense, so they are synonyms. The other pairs are opposites.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-80", "question": "One word for “a person who studies the origin and history of words”:", "options": ["Etymologist", "Entomologist", "Philologist", "Lexicographer"], "answer": 0, "explanation": "An etymologist studies word origins. An entomologist studies insects (the classic trap), and a lexicographer compiles dictionaries.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-81", "question": "Fill in the blank with the most suitable word: The witness's ___ testimony, full of contradictions, was rejected by the court.", "options": ["cogent", "lucid", "compelling", "incoherent"], "answer": 3, "explanation": "Testimony full of contradictions is incoherent (lacking logical connection). Cogent, lucid and compelling would make the court accept it.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id":"eng-vocabulary-82","question":"The idiom “to have feet of clay” means:","options":["To be very slow and clumsy in one's movements","To be firmly rooted in one's home soil","To have a hidden flaw despite being admired","To be humble about one's own achievements"],"answer":2,"explanation":"From the statue in the Book of Daniel with a gold head but clay feet: an admired person with a hidden flaw.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id": "eng-vocabulary-83", "question": "Choose the synonym of “Recondite”.", "options": ["Reconciled", "Abstruse", "Recent", "Obvious"], "answer": 1, "explanation": "Recondite means little known and difficult to understand, i.e. abstruse. 'Obvious' is the opposite; the other two only look alike.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-84", "question": "Choose the synonym of “Feeble”.", "options": ["Weak", "Angry", "Quick", "Strong"], "answer": 0, "explanation": "Feeble means lacking strength, i.e. weak. Strong is its antonym.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-vocabulary-85", "question": "Choose the antonym of “Victory”.", "options": ["Success", "Defeat", "Conquest", "Triumph"], "answer": 1, "explanation": "The opposite of victory is defeat. Triumph, success and conquest are near-synonyms.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id":"eng-vocabulary-86","question":"One word for “a person who does not eat meat”:","options":["Herbivore","Insectivore","Vegan","Vegetarian"],"answer":3,"explanation":"A vegetarian does not eat meat. A vegan also avoids all animal products such as milk, while herbivore and insectivore describe animals' diets.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"eng-vocabulary-87","question":"Choose the synonym of “Arduous”.","options":["Effortless","Audacious","Laborious","Ardent"],"answer":2,"explanation":"Arduous means needing great effort: laborious. Ardent (passionate) and audacious (daring) only look or sound similar, and effortless is the opposite.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-88","question":"Choose the antonym of “Exonerate”.","options":["Absolve","Incriminate","Clear of blame","Acquit"],"answer":1,"explanation":"To exonerate is to clear someone of blame; to incriminate is to make them appear guilty. Absolve, acquit and 'clear of blame' all mean the same as exonerate, which is the trap in an antonym question.","difficulty":"moderate","source":"SSC CGL · CDS"},
  {"id": "eng-vocabulary-89", "question": "One word for “a person who studies or collects coins”:", "options": ["Numismatist", "Archivist", "Cartographer", "Philatelist"], "answer": 0, "explanation": "A numismatist collects or studies coins (and medals). A philatelist collects stamps.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-90","question":"The idiom “to spill the beans” means:","options":["To make a mess while eating","To lose money in a deal","To waste good food","To reveal a secret"],"answer":3,"explanation":"To spill the beans is to let out secret information, often by accident.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id": "eng-vocabulary-91", "question": "One word for “a remedy for all diseases or problems”:", "options": ["Antidote", "Placebo", "Panacea", "Vaccine"], "answer": 2, "explanation": "A panacea is a cure-all. An antidote counters a particular poison; a placebo has no active ingredient.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-92","question":"Choose the synonym of “Eminent”.","options":["Unremarkable","Imminent","Distinguished","Inconspicuous"],"answer":2,"explanation":"Eminent means famous and respected: distinguished. Imminent (about to happen) is a commonly confused word, and unremarkable and inconspicuous mean the opposite.","difficulty":"moderate","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-93","question":"The idiom “to steal someone's thunder” means:","options":["To rob someone of their belongings at night","To lose one's temper loudly in front of others","To frighten someone badly with a sudden loud noise","To take the credit someone else expected to get"],"answer":3,"explanation":"To steal someone's thunder is to win the praise or attention another person was about to get, often by doing or saying their thing first.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id": "eng-vocabulary-94", "question": "Choose the synonym of “Insipid”.", "options": ["Vivid", "Bland", "Spicy", "Insolent"], "answer": 1, "explanation": "Insipid means lacking flavour or interest: bland. Insolent (rude) is a look-alike trap; vivid is nearly opposite.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-95", "question": "Choose the antonym of “Gregarious”.", "options": ["Reclusive", "Talkative", "Friendly", "Sociable"], "answer": 0, "explanation": "Gregarious means fond of company. A reclusive person avoids others, so it is the antonym; the other three are close in meaning to gregarious.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-96", "question": "One word for “a speech or piece of writing praising someone, especially one who has just died”:", "options": ["Elegy", "Epitaph", "Eulogy", "Epilogue"], "answer": 2, "explanation": "A eulogy is a speech of praise, typically at a funeral. An elegy is a mournful poem, an epitaph is the inscription on a tomb and an epilogue ends a book.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id":"eng-vocabulary-97","question":"One word for “a word or phrase that reads the same backwards as forwards”:","options":["Palindrome","Onomatopoeia","Acronym","Anagram"],"answer":0,"explanation":"A palindrome reads the same both ways (madam, level). An anagram rearranges letters to form a new word.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-98", "question": "The idiom “to show the white feather” means:", "options": ["To surrender honourably", "To show cowardice", "To make peace", "To show off one's wealth"], "answer": 1, "explanation": "To show the white feather is to act in a cowardly way. Surrender is suggested by a white flag, which is the trap.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id":"eng-vocabulary-99","question":"Choose the synonym of “Mendacious”.","options":["Begging","Repairing","Munificent","Untruthful"],"answer":3,"explanation":"Mendacious means given to telling lies: untruthful. 'Begging' confuses it with mendicant, and 'repairing' with mend.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-100","question":"Choose the antonym of “Fastidious”.","options":["Persnickety","Undemanding","Particular","Meticulous"],"answer":1,"explanation":"A fastidious person is hard to please and very attentive to detail. Undemanding is the opposite; persnickety, particular and meticulous are near-synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-101", "question": "Choose the correctly spelt word for “government by unelected officials and red tape”.", "options": ["Bureaucracy", "Bureacracy", "Beurocracy", "Beaurocracy"], "answer": 0, "explanation": "The correct spelling is bureaucracy, from French bureau (desk) + -cracy (rule).", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-102","question":"The phrase “a red herring” means:","options":["A dangerous person hiding among friends","An unexpected profit from a risky venture","A rare and costly delicacy served only at royal feasts","Something that distracts from the real issue"],"answer":3,"explanation":"A red herring is a clue or point that draws attention away from the real question, as in a detective story. It has nothing to do with food in this use.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id": "eng-vocabulary-103", "question": "One word for “favouritism shown by people in power to their relatives, especially in giving jobs”:", "options": ["Despotism", "Cronyism", "Nepotism", "Chauvinism"], "answer": 2, "explanation": "Nepotism is favouring relatives. Cronyism is favouring friends and associates, the closest trap; despotism is tyrannical rule.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-104", "question": "One word for “a position that gives pay or status but needs little or no work”:", "options": ["Honorarium", "Sinecure", "Sabbatical", "Stipend"], "answer": 1, "explanation": "A sinecure is a paid post with almost no duties. A stipend is a fixed allowance and an honorarium a fee for a service otherwise unpaid.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-105", "question": "Choose the word nearest in meaning to PERSPICACIOUS.", "options": ["Discerning", "Transparent", "Persistent", "Sweaty"], "answer": 0, "explanation": "Perspicacious means having keen insight: discerning or shrewd. 'Sweaty' plays on perspire and 'transparent' on perspicuous (clearly expressed), both traps.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-106", "question": "Choose the word opposite in meaning to MAGNANIMOUS.", "options": ["Noble", "Generous", "Petty", "Large"], "answer": 2, "explanation": "Magnanimous means generous in forgiving, big-hearted. Its opposite is petty (small-minded). 'Large' plays on 'magna'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-107", "question": "The idiom “to cool one's heels” means:", "options": ["To calm down after anger", "To run away quickly", "To relax after hard work", "To be kept waiting"], "answer": 3, "explanation": "To cool one's heels is to be made to wait, usually by someone more powerful. 'Calm down' is the tempting literal guess.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-108", "question": "One word for “a person whose knowledge spans many different subjects”:", "options": ["Polyglot", "Polymath", "Dilettante", "Pedant"], "answer": 1, "explanation": "A polymath has wide learning in many fields. A polyglot knows many languages; a dilettante dabbles without depth; a pedant fusses over minor rules.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id":"eng-vocabulary-109","question":"In the sentence “The lawyer's specious argument impressed the jury at first but collapsed under scrutiny”, the word “specious” means:","options":["Plausible-looking but actually false","Specific, precise and well documented","Rude, aggressive and insulting","Spacious, wide-ranging and detailed"],"answer":0,"explanation":"Specious describes something that looks plausible but is misleading or false, which fits an argument that later collapses.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-110","question":"The idiom “to bell the cat” means:","options":["To make a lot of noise to draw attention","To warn others loudly of a danger that is coming","To take on a risky task for the common good","To punish a wrongdoer in front of everyone"],"answer":2,"explanation":"From the fable of the mice: everyone agrees the cat should wear a bell, but no one dares to tie it. To bell the cat is to take on that dangerous job.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id": "eng-vocabulary-111", "question": "One word for “a person who constantly and needlessly worries about his or her health”:", "options": ["Misanthrope", "Valetudinarian", "Hypocrite", "Hypochondriac"], "answer": 3, "explanation": "A hypochondriac is anxious about imagined illness. A valetudinarian is someone actually in weak health (or over-concerned with it), so hypochondriac is the precise word for needless worry; a hypocrite pretends to virtue.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-112", "question": "Choose the correctly spelt word for “an expert judge in matters of taste”.", "options": ["Connoissuer", "Conoisseur", "Connoiseur", "Connoisseur"], "answer": 3, "explanation": "Connoisseur (an expert judge of taste) has double n, double s and ends in -eur.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-113", "question": "Choose the antonym of “Ingenuous”.", "options": ["Frank", "Naive", "Artful", "Unintelligent"], "answer": 2, "explanation": "Ingenuous means innocent and candid, so its opposite is artful (crafty). 'Unintelligent' is the trap, treating it as ingenious (clever).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id":"eng-vocabulary-114","question":"Choose the antonym of “Frugal”.","options":["Extravagant","Thrifty","Parsimonious","Economical"],"answer":0,"explanation":"Frugal means sparing or economical with money; its opposite is extravagant (spending wastefully). Thrifty, parsimonious and economical all lean the same way as frugal.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-115","question":"One word for “a person who collects postage stamps”:","options":["Numismatist","Philatelist","Cartographer","Lexicographer"],"answer":1,"explanation":"A philatelist collects or studies stamps. A numismatist collects coins, a cartographer makes maps and a lexicographer compiles dictionaries.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-116","question":"The idiom “to break the ice” means:","options":["To do something bold and dangerous","To cause a serious quarrel between friends","To reveal a secret that was well kept","To ease the first awkwardness among people"],"answer":3,"explanation":"Breaking the ice is easing the initial awkwardness among people who have just met, e.g. with a joke or a game.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-117","question":"Choose the synonym of “Tenacious”.","options":["Vacillating","Feeble","Persistent","Hesitant"],"answer":2,"explanation":"Tenacious means holding firmly to a purpose, i.e. persistent and determined. Vacillating, hesitant and feeble are nearly opposite.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-118","question":"One word for “an animal that can live both on land and in water”:","options":["Mammal","Amphibian","Reptile","Carnivore"],"answer":1,"explanation":"Amphibians (such as frogs) live both on land and in water. Reptiles, though some swim, are not defined by this.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-119","question":"The hotel offers free ___ to delegates. Choose the correctly spelt word for the blank.","options":["Accommodation","Acommodation","Accomodation","Accommadation"],"answer":0,"explanation":"'Accommodation' has a double c and a double m (ac-com-mo-da-tion). The usual errors drop one c or one m, or turn the middle o into an a; remember it has room to accommodate both pairs.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-120","question":"Choose the synonym of “Capricious”.","options":["Cautious","Steady","Predictable","Whimsical"],"answer":3,"explanation":"Capricious means given to sudden, unaccountable changes of mood or behaviour, i.e. whimsical. Steady and predictable are its antonyms, and cautious describes care, not changeability.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-121","question":"Choose the antonym of “Affluent”.","options":["Prosperous","Opulent","Indigent","Influential"],"answer":2,"explanation":"Affluent means wealthy; indigent means poor and needy. Opulent and prosperous are synonyms of affluent; 'influential' merely sounds similar.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-122","question":"Choose the synonym of “Placate”.","options":["Replace","Provoke","Postpone","Pacify"],"answer":3,"explanation":"To placate is to calm someone's anger — to pacify or appease. Provoke means the opposite.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-123","question":"Choose the antonym of “Clandestine”.","options":["Covert","Secret","Open","Illegal"],"answer":2,"explanation":"Clandestine means kept secret, especially because it is illicit; its opposite is open. Secret and covert are synonyms.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-124","question":"One word for “the murder of one's own brother”:","options":["Patricide","Fratricide","Regicide","Infanticide"],"answer":1,"explanation":"Fratricide is killing one's brother (Latin frater). Patricide is killing one's father, regicide a king, and infanticide an infant.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-125","question":"One word for “words inscribed on a tomb in memory of the person buried there”:","options":["Epitaph","Epigram","Epilogue","Epithet"],"answer":0,"explanation":"An epitaph is the inscription on a tomb. An epigram is a short witty saying, an epilogue a concluding section, and an epithet a descriptive name.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-126","question":"The idiom “to turn a blind eye” means:","options":["To pretend not to see something wrong","To lose one's eyesight in an accident","To look at something angrily and coldly","To keep careful watch over something"],"answer":0,"explanation":"To turn a blind eye is to deliberately ignore something, usually wrongdoing, that one knows about.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-127","question":"The idiom “a white elephant” refers to:","options":["A rare and precious gift that is given only by kings","A possession costly to maintain but of little use","A powerful but gentle and patient person","An unexpected success that surprises everyone"],"answer":1,"explanation":"A white elephant is something expensive to keep that brings little benefit — for example, a huge stadium that is rarely used.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-128","question":"Choose the synonym of “Laudable”.","options":["Reprehensible","Audible","Praiseworthy","Questionable"],"answer":2,"explanation":"Laudable means deserving praise. 'Audible' (able to be heard) is a sound-alike trap, and reprehensible is the opposite.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-129","question":"One word for “a person who leaves his own country to settle permanently in another”:","options":["Tourist","Immigrant","Refugee","Emigrant"],"answer":3,"explanation":"From the point of view of the country he leaves, he is an emigrant (e- = out). He is an immigrant to the country he enters; a refugee flees danger or persecution.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-130","question":"Which of these four words is spelt incorrectly: Occurence, Committee, Privilege, Rhythm?","options":["Committee","Occurence","Privilege","Rhythm"],"answer":1,"explanation":"The correct spelling is 'occurrence', with double r and -ence. The other three are spelt correctly.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-131","question":"Fill in the blank with the suitable idiom: The new manager decided to ___ and confront the union leaders directly instead of avoiding the issue.","options":["keep his head below the parapet","sit on the fence","let sleeping dogs lie","take the bull by the horns"],"answer":3,"explanation":"To take the bull by the horns is to face a difficult situation boldly. Keeping one's head below the parapet, sitting on the fence and letting sleeping dogs lie all mean avoiding risk or action.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-132","question":"Choose the synonym of “Fortuitous”.","options":["Carefully planned in advance","Extremely dangerous","Happening by chance","Well guarded"],"answer":2,"explanation":"Fortuitous means happening by accident or chance, the opposite of carefully planned. It is often confused with 'fortunate', but a fortuitous event need not be a lucky one.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-133","question":"Choose the synonym of “Pernicious”.","options":["Harmful","Thrifty","Precise","Persistent"],"answer":0,"explanation":"Pernicious means having a harmful effect, especially gradually or subtly. 'Thrifty' might be guessed by confusing it with 'parsimonious'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-134","question":"Choose the antonym of “Spurious”.","options":["Counterfeit","False","Genuine","Speedy"],"answer":2,"explanation":"Spurious means false or not genuine; its opposite is genuine. False and counterfeit are synonyms, and speedy is only a sound-alike.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-135","question":"Choose the antonym of “Acrimonious”.","options":["Quarrelsome","Bitter","Hostile","Amicable"],"answer":3,"explanation":"Acrimonious means bitter and angry (as in an acrimonious debate); amicable means friendly. Bitter and hostile are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-136","question":"One word for “government by a small group of powerful people”:","options":["Monarchy","Oligarchy","Plutocracy","Theocracy"],"answer":1,"explanation":"Oligarchy is rule by a few. Plutocracy is rule by the wealthy (who may or may not be few), theocracy rule by religious authority, monarchy rule by one sovereign.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-137","question":"One word for “an extreme fear of heights”:","options":["Acrophobia","Agoraphobia","Hydrophobia","Xenophobia"],"answer":0,"explanation":"Acrophobia is fear of heights (Greek akron, peak). Agoraphobia is fear of open or crowded places, hydrophobia of water and xenophobia of foreigners.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-138","question":"The idiom “to have an axe to grind” means:","options":["To have a lot of hard work to do","To have a private, selfish motive","To be ready to fight at any moment","To complain constantly"],"answer":1,"explanation":"Someone with an axe to grind has a personal interest or grievance behind what he says or does.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-139","question":"The idiom “to rest on one's laurels” means:","options":["To rely on past success and make no further effort","To retire with honour after a long career","To celebrate a victory at length with friends and family","To take a well-deserved holiday after hard work"],"answer":0,"explanation":"Resting on one's laurels is relying on past achievements instead of continuing to work. It is usually critical, not complimentary.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-140","question":"Choose the synonym of “Querulous”.","options":["Uncertain","Inquisitive","Quarrelsome","Complaining"],"answer":3,"explanation":"Querulous means complaining in a petulant or whining way. 'Inquisitive' is suggested by 'query', and 'quarrelsome' by the sound, but neither is the meaning.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-141","question":"Which of these four words is spelt incorrectly: Embarassment, Questionnaire, Millennium, Lieutenant?","options":["Millennium","Questionnaire","Embarassment","Lieutenant"],"answer":2,"explanation":"The correct spelling is 'embarrassment', with double r and double s. The other words are spelt correctly.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-142","question":"One word for “a speech in a play in which a character, alone on stage, speaks his thoughts aloud”:","options":["Soliloquy","Monologue","Dialogue","Prologue"],"answer":0,"explanation":"A soliloquy is spoken by a character alone, to himself. A monologue is a long speech by one person that others may hear; a prologue is an introduction.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-143","question":"Choose the antonym of “Augment”.","options":["Enlarge","Diminish","Supplement","Amplify"],"answer":1,"explanation":"Augment means to increase; its opposite is diminish. Enlarge, supplement and amplify all mean adding to something.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-144","question":"Choose the synonym of “Sagacious”.","options":["Lustful","Wise","Talkative","Ferocious"],"answer":1,"explanation":"Sagacious means having keen judgement — wise, shrewd. 'Lustful' is the meaning of the look-alike 'salacious'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-145","question":"Choose the antonym of “Intrepid”.","options":["Valiant","Fearless","Daring","Timid"],"answer":3,"explanation":"Intrepid means fearless; its opposite is timid. Fearless, daring and valiant are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-146","question":"One word for “the belief that God is present in everything in nature”:","options":["Pantheism","Polytheism","Monotheism","Atheism"],"answer":0,"explanation":"Pantheism (pan = all) identifies God with the universe and nature. Polytheism is belief in many gods, monotheism in one God, and atheism in none.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-147","question":"The idiom “to carry coals to Newcastle” means:","options":["To bring bad news to someone who least expects it","To do very hard and dirty physical work in mines","To take something where it is already plentiful","To make a large profit from trading in goods"],"answer":2,"explanation":"Newcastle was a famous coal-mining town, so carrying coal there is pointless — the idiom means a superfluous action.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-148","question":"The phrase “Hobson's choice” means:","options":["A wise choice made by an expert after study","A choice made only after long and careful thought","A choice between two equally good options that are on offer","No real choice at all: take what is offered or nothing"],"answer":3,"explanation":"Hobson, a stable owner, let customers take only the horse nearest the door or none at all. So 'Hobson's choice' is no choice. A choice between two unpleasant options is a 'dilemma'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-149","question":"One word for “a person who is new to a profession, subject or activity”:","options":["Veteran","Neophyte","Mentor","Charlatan"],"answer":1,"explanation":"A neophyte is a beginner or novice. A veteran is highly experienced, a mentor guides others, and a charlatan falsely claims skill.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-150","question":"Choose the synonym of “Munificent”.","options":["Municipal","Magnificent","Generous","Miserly"],"answer":2,"explanation":"Munificent means very generous in giving. 'Magnificent' is a sound-alike trap, and 'miserly' is the opposite.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-151","question":"Choose the antonym of “Esoteric”.","options":["Commonplace","Obscure","Mysterious","Impenetrable"],"answer":0,"explanation":"Esoteric means understood only by a small circle of specialists; commonplace (ordinary, widely known) is its opposite. Obscure, mysterious and impenetrable all lean the same way as esoteric.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-152","question":"Choose the correctly spelt word: A good doctor must be ___ about following up with patients.","options":["Concientious","Consciencious","Conscientous","Conscientious"],"answer":3,"explanation":"'Conscientious' (careful and diligent) keeps 'science' inside it: con-sci-en-tious.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-153","question":"Choose the synonym of “Enervate”.","options":["Irritate","Energise","Weaken","Encourage"],"answer":2,"explanation":"Enervate means to drain of energy — to weaken. It looks like 'energise', its near opposite, which is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-154","question":"Choose the synonym of “Noisome”.","options":["Noisy","Offensive","Troublesome","Cheerful"],"answer":1,"explanation":"Noisome means offensive or disgusting, especially in smell ('a noisome drain'). It has nothing to do with noise.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-155","question":"Choose the synonym of “Restive”.","options":["Restless","Restful","Calm","Exhausted"],"answer":0,"explanation":"Restive means restless, uneasy or unwilling to be controlled ('the crowd grew restive'). 'Restful' and 'calm' are near opposites.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-156","question":"In the sentence “The enormity of the crime shocked the whole nation”, the word 'enormity' means:","options":["Long duration","Huge size","Widespread publicity","Great wickedness"],"answer":3,"explanation":"In careful usage 'enormity' means extreme wickedness or seriousness. Using it for mere size ('enormousness') is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-157","question":"In the sentence “The dispute should be settled by a disinterested arbitrator”, the word 'disinterested' means:","options":["Bored","Impartial","Unqualified","Unpaid"],"answer":1,"explanation":"Disinterested means having no personal stake — impartial. 'Uninterested' means not interested or bored, which is the common confusion.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-158","question":"Choose the synonym of “Venal”.","options":["Poisonous","Pardonable","Corruptible","Sacred"],"answer":2,"explanation":"Venal means open to bribery. 'Pardonable' is the meaning of 'venial' (a venial sin), and 'poisonous' that of 'venomous'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-159","question":"Choose the antonym of “Quiescent”.","options":["Active","Dormant","Latent","Inactive"],"answer":0,"explanation":"Quiescent means in a state of inactivity or dormancy; its opposite is active. Dormant, latent and inactive are synonyms.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-160","question":"Choose the antonym of “Felicitous”.","options":["Well-chosen","Apt","Inappropriate","Happily expressed"],"answer":2,"explanation":"Felicitous means well-chosen or apt ('a felicitous phrase'); its opposite is inappropriate. The other three options are synonyms.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-161","question":"Choose the antonym of “Penchant”.","options":["Aversion","Liking","Inclination","Fondness"],"answer":0,"explanation":"A penchant is a strong liking or inclination; its opposite is aversion (strong dislike).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-162","question":"One word for “government by the mob”:","options":["Anarchy","Ochlocracy","Kleptocracy","Oligarchy"],"answer":1,"explanation":"Ochlocracy (Greek okhlos, mob) is mob rule. Anarchy is the absence of government, kleptocracy rule by thieves, and oligarchy rule by a few.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-163","question":"One word for “the study of ancient handwriting and manuscripts”:","options":["Orthography","Historiography","Calligraphy","Palaeography"],"answer":3,"explanation":"Palaeography studies old handwriting and manuscripts. Historiography is the study of how history is written, calligraphy the art of beautiful writing and orthography correct spelling.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-164","question":"One word for “an exact copy of a document, especially one showing its original appearance”:","options":["Facsimile","Forgery","Manuscript","Transcript"],"answer":0,"explanation":"A facsimile reproduces a document exactly. A transcript copies only the words; a forgery is a copy made to deceive.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-165","question":"The idiom “to cross the Rubicon” means:","options":["To betray a trusted friend for gain","To travel to a distant and foreign land","To overcome a minor difficulty with ease","To take a step that cannot be reversed"],"answer":3,"explanation":"Julius Caesar's crossing of the river Rubicon in 49 BC committed him to civil war. The idiom means passing a point of no return.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-166","question":"The phrase “the sword of Damocles” refers to:","options":["A sudden, decisive victory over a rival","A legendary weapon of great power","An ever-present threat hanging over someone","A difficult problem solved by force alone, not by patience"],"answer":2,"explanation":"Damocles sat beneath a sword hung by a single hair, showing the ever-present peril of a powerful position. A difficult problem solved by force is 'cutting the Gordian knot'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-167","question":"The idiom “to eat humble pie” means:","options":["To live in poverty on very little","To admit one's mistake and apologise","To eat very little out of modesty","To accept a low-paid job without complaint"],"answer":1,"explanation":"Eating humble pie is being forced to admit that one was wrong, usually with humiliation.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-168","question":"Fill in the blank with the suitable phrase: Everyone expected the senior lawyers to win the debate, but the quiet first-year student turned out to be a ___ and took the trophy.","options":["white elephant","black sheep","lame duck","dark horse"],"answer":3,"explanation":"A dark horse is a little-known competitor who unexpectedly wins. A black sheep is a disgraced family member, and a lame duck an ineffective person.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-169","question":"The idiom “to draw the long bow” means:","options":["To aim carefully at a distant target","To plan a long-term strategy in advance","To exaggerate or tell tall stories","To show great patience under pressure"],"answer":2,"explanation":"To draw the long bow is to exaggerate. The archery image is a trap that suggests long-range aiming.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-170","question":"Choose the synonym of “Lugubrious”.","options":["Mournful","Slippery","Greedy","Talkative"],"answer":0,"explanation":"Lugubrious means looking or sounding sad and dismal. 'Slippery' would be 'lubricious', a sound-alike.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-171","question":"Choose the synonym of “Insouciant”.","options":["Insulting","Nonchalant","Apprehensive","Insolvent"],"answer":1,"explanation":"Insouciant means showing casual lack of concern, i.e. nonchalant or carefree. 'Apprehensive' is the opposite; 'insulting' and 'insolvent' are look-alike traps.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-172","question":"Choose the correctly spelt word: The new rules will ___ all earlier circulars on the subject.","options":["Superseed","Supercede","Supersede","Supperseed"],"answer":2,"explanation":"'Supersede' comes from Latin supersedere and is spelt with -sede; 'supercede' is a very common misspelling.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-173","question":"In the sentence “He is an inveterate liar, so do not trust his promises”, 'inveterate' means:","options":["Occasional","Habitual","Clever","Repentant"],"answer":1,"explanation":"Inveterate means having a long-established habit that is unlikely to change. 'Occasional' and 'repentant' contradict this.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-174","question":"One word for “a person who is devoted to luxury and sensual pleasure”:","options":["Ascetic","Teetotaller","Glutton","Sybarite"],"answer":3,"explanation":"A sybarite (from Sybaris, a Greek city famous for luxury) indulges in every comfort. An ascetic is the opposite, a teetotaller merely avoids alcohol, and a glutton overindulges only in food.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-175","question":"One word for “government by the least qualified or most unprincipled citizens”:","options":["Kleptocracy","Kakistocracy","Ochlocracy","Gerontocracy"],"answer":1,"explanation":"Kakistocracy comes from Greek “kakistos”, worst. Kleptocracy is rule by thieves, ochlocracy is mob rule, and gerontocracy is rule by the old.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-176","question":"One word for “a word formed from the initial letters of other words and pronounced as a single word” (e.g. NASA):","options":["Initialism","Acronym","Anagram","Antonym"],"answer":1,"explanation":"An acronym is read as a word (NASA, UNESCO). An initialism is read letter by letter (BBC, CBI), and an anagram rearranges the letters of a word.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-177","question":"The idiom “to throw down the gauntlet” means:","options":["To issue a challenge","To accept defeat","To end a long quarrel","To give up a claim"],"answer":0,"explanation":"A knight threw down his glove (gauntlet) to challenge an opponent; picking it up meant accepting. “Accepting defeat” is “throwing in the towel”, a common mix-up.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-178","question":"The phrase “a red-letter day” means:","options":["A memorable or especially happy day","A day of danger or public warning","A day of national mourning","A day on which debts fall due for payment"],"answer":0,"explanation":"Church calendars printed feast days in red ink, so a red-letter day is a special, memorable day. The colour red here has nothing to do with danger.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-179","question":"Fill in the blank: The inquiry report was a ___; it cleared every senior official of blame despite clear evidence of their involvement.","options":["red herring","whitewash","white elephant","blue moon"],"answer":1,"explanation":"A whitewash is an attempt to cover up wrongdoing or clear people of blame. A red herring is a distraction, a white elephant is a costly useless possession, and “once in a blue moon” means rarely.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-180","question":"Fill in the blank with the correct collocation: The state government has ___ a ban on single-use plastic bags.","options":["inflicted","levied","exerted","imposed"],"answer":3,"explanation":"A ban, a rule or a restriction is “imposed”. Taxes are “levied”, punishment or damage is “inflicted”, and pressure or force is “exerted”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-181","question":"Fill in the blank: Despite repeated warnings from his doctor, he continued to ___ a deaf ear to all advice about his diet.","options":["lend","turn","give","show"],"answer":1,"explanation":"To refuse to listen is to “turn a deaf ear” to something. “Lend an ear” means the opposite: to listen sympathetically.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-182","question":"Fill in the blanks: The ___ economist warned the panel of an ___ collapse in rural demand.","options":["eminent; imminent","imminent; eminent","eminent; eminent","immanent; imminent"],"answer":0,"explanation":"“Eminent” means distinguished and describes the economist; “imminent” means about to happen and describes the collapse. “Immanent” means inherent, which fits neither blank.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-183","question":"Fill in the blank: The deep-red scarf ___ her ivory saree perfectly.","options":["compliments","implements","complements","completes"],"answer":2,"explanation":"To “complement” is to go well with or complete something by contrast; to “compliment” is to praise. A scarf cannot praise a saree.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-184","question":"Fill in the blank: The new director hopes to ___ sweeping changes in the way the department handles complaints.","options":["affect","afflict","infect","effect"],"answer":3,"explanation":"As a verb, “effect” means to bring about (effect changes); “affect” means to influence. “Affect sweeping changes” would mean to influence changes that already exist.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-185","question":"Find the odd one out in meaning:","options":["Bellicose","Belligerent","Pugnacious","Placid"],"answer":3,"explanation":"Bellicose, belligerent and pugnacious all mean eager to fight; placid means calm and peaceful.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-186","question":"Choose the word opposite in meaning to IMPECUNIOUS as used: “Born into an impecunious family, he worked his way through college.”","options":["Wealthy","Penniless","Imprudent","Impatient"],"answer":0,"explanation":"Impecunious means having little or no money, so its opposite is wealthy. “Penniless” is a synonym, and the other two only look similar.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-187","question":"Choose the word opposite in meaning to ABSTEMIOUS.","options":["Self-denying","Temperate","Gluttonous","Abstinent"],"answer":2,"explanation":"Abstemious means moderate in eating and drinking; its opposite is gluttonous. The other three options are near-synonyms, the classic trap in antonym questions.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-188","question":"Choose the word nearest in meaning to PROPITIATE as used: “The villagers offered prayers to propitiate the angry deity.”","options":["Provoke","Appease","Predict","Propagate"],"answer":1,"explanation":"To propitiate is to win or regain someone's favour by doing something that pleases them: to appease. “Provoke” is nearly its opposite.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-189","question":"In the sentence “The unexpected question left the minister completely nonplussed”, NONPLUSSED means:","options":["Unbothered","Unimpressed","Delighted","Perplexed"],"answer":3,"explanation":"In standard British and Indian usage, “nonplussed” means so surprised and confused that one does not know how to react. Reading it as “unbothered” is a common error.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-190","question":"In the sentence “His quixotic plan to end poverty in the district within a month won applause but no funding”, QUIXOTIC means:","options":["Hastily and carelessly prepared","Idealistic but impractical","Cleverly designed to deceive","Strictly economical"],"answer":1,"explanation":"From Don Quixote, “quixotic” describes noble but unrealistic ideals, which explains the applause without funding. It has nothing to do with being quick.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-191","question":"Choose the word nearest in meaning to INTRANSIGENT as used: “The intransigent landlord rejected every compromise the tenants offered.”","options":["Temporary","Unapproachable","Uncompromising","Untrustworthy"],"answer":2,"explanation":"Intransigent means refusing to change one's views or agree: uncompromising. “Temporary” is a confusion with “transient”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-192","question":"Choose the word opposite in meaning to DILATORY as used: “The dilatory contractor missed every deadline.”","options":["Tardy","Dilated","Prompt","Sluggish"],"answer":2,"explanation":"Dilatory means slow and causing delay, so its opposite is prompt. “Tardy” and “sluggish” are synonyms, and “dilated” (widened) only looks similar.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-193","question":"One word for “a person who opposes new technology or new ways of working”:","options":["Luddite","Philistine","Neophyte","Iconoclast"],"answer":0,"explanation":"Luddites were workers who smashed textile machinery; the word now means anyone opposed to new technology. A philistine is hostile to culture, a neophyte is a beginner and an iconoclast attacks established beliefs.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-194","question":"One word for “a collection of dried and preserved plant specimens”:","options":["Herbarium","Arboretum","Conservatory","Aviary"],"answer":0,"explanation":"A herbarium stores dried, pressed plants. An arboretum is a garden of living trees, a conservatory is a glasshouse for living plants, and an aviary houses birds.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-195","question":"One word for “a person who is easily deceived or tricked”:","options":["Credible","Culpable","Gullible","Callow"],"answer":2,"explanation":"A gullible person believes whatever he is told. “Credible” means believable (it is often confused with “credulous”), “culpable” means blameworthy, and “callow” means immature.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-196","question":"One word for “the practice of a woman having more than one husband at the same time”:","options":["Polygamy","Polygyny","Polyandry","Matriarchy"],"answer":2,"explanation":"Polyandry (Greek 'andr-', man) is having several husbands. Polygyny is having several wives, polygamy is the general term, and matriarchy is rule or descent through women, not a form of marriage.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-197","question":"The idiom “to steal a march on someone” means:","options":["To rob someone secretly at night","To lead a protest march through the streets","To march faster than one's own troops","To gain an advantage by acting first"],"answer":3,"explanation":"To steal a march on rivals is to get ahead of them by doing something first, often quietly; nothing is actually stolen.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-198","question":"The idiom “to pass the buck” means:","options":["To shift responsibility to someone else","To pay a bribe to an official","To pass an examination easily and with good marks","To lend money to a friend in need"],"answer":0,"explanation":"To pass the buck is to make someone else responsible for a problem or decision; it has nothing to do with money despite the slang sense of “buck”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-199","question":"Choose the word nearest in meaning to IGNOMINIOUS as used: “After the army's ignominious retreat, the general resigned.”","options":["Ignorant","Disgraceful","Anonymous","Inconspicuous"],"answer":1,"explanation":"Ignominious means bringing public shame or humiliation: disgraceful. 'Ignorant' and 'anonymous' only share sounds with it, and inconspicuous (unnoticed) misses the sense of shame.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-200","question":"In the sentence “Spare us your sanctimonious lectures on honesty; you cheated in the last audit yourself”, SANCTIMONIOUS means:","options":["Sacred","Officially sanctioned","Self-righteous","Humble"],"answer":2,"explanation":"Sanctimonious means making a show of being morally superior to others: self-righteous. The context (a cheat lecturing on honesty) rules out “sacred” and “humble”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-201","question":"Choose the word opposite in meaning to ASSIDUOUS.","options":["Diligent","Assertive","Persevering","Negligent"],"answer":3,"explanation":"Assiduous means showing great care and constant effort, so its opposite is negligent. “Diligent” and “persevering” are synonyms.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-202","question":"Choose the word nearest in meaning to MOLLIFY as used: “The manager tried to mollify the angry customer with a full refund.”","options":["Mortify","Pacify","Modify","Provoke"],"answer":1,"explanation":"To mollify is to calm someone's anger: to pacify. “Mortify” means to humiliate, and “provoke” is the opposite.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-203","question":"Choose the word nearest in meaning to VACILLATE as used: “Leaders who vacillate in a crisis soon lose public trust.”","options":["Waver","Ventilate","Validate","Act rashly"],"answer":0,"explanation":"To vacillate is to keep changing one's mind and fail to decide: to waver. Acting rashly is the opposite fault.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-204","question":"In the sentence “He greeted the minister's lofty promises with a sardonic smile”, SARDONIC means:","options":["Deeply sorrowful","Openly cheerful","Grimly mocking","Shy and nervous"],"answer":2,"explanation":"Sardonic means scornfully or cynically mocking, which suits a reaction to empty promises. It has nothing to do with sadness despite the similar sound.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-205","question":"Choose the word opposite in meaning to PELLUCID as used: “Her pellucid prose made even tax law easy to follow.”","options":["Lucid","Limpid","Polished","Obscure"],"answer":3,"explanation":"Pellucid means very clear and easy to understand, so its opposite is obscure. “Lucid” and “limpid” are synonyms, the usual trap.","difficulty":"hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-206","question":"In the sentence “After a desultory search, the clerk declared the file lost”, DESULTORY means:","options":["Desperate and frantic","Thorough and painstaking","Secretive and furtive","Half-hearted and aimless"],"answer":3,"explanation":"Desultory means lacking a plan, purpose or enthusiasm, which is why the file was so quickly declared lost. “Thorough” is its opposite.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-207","question":"In the sentence “He cast a surreptitious glance at his phone during the interview”, SURREPTITIOUS means:","options":["Stealthy","Repeated","Superstitious","Surprised"],"answer":0,"explanation":"Surreptitious means done secretly so as not to be noticed: stealthy. “Repeated” is a guess from “repetition” inside the word.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-208","question":"Choose the word opposite in meaning to OSTRACISE as used: “The village council ostracised the family for marrying outside the caste.”","options":["Banish","Boycott","Welcome","Exclude"],"answer":2,"explanation":"To ostracise is to exclude someone from a group or society, so the opposite is to welcome (accept) them. The other three are near-synonyms.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-209","question":"Choose the word opposite in meaning to EXCULPATE.","options":["Absolve","Exonerate","Expostulate","Incriminate"],"answer":3,"explanation":"To exculpate (Latin 'ex culpa', from blame) is to clear someone of blame; the opposite is to incriminate. 'Absolve' and 'exonerate' are synonyms, and 'expostulate' (to protest) is only a look-alike.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-210","question":"In the sentence “The auditors found an egregious error in the balance sheet”, EGREGIOUS means:","options":["Barely noticeable","Outstandingly bad","Highly commendable","Highly sociable"],"answer":1,"explanation":"In modern usage “egregious” means shockingly bad. “Highly sociable” confuses it with “gregarious”, and the old sense “remarkably good” is obsolete.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-211","question":"Choose the word opposite in meaning to VENERATE.","options":["Despise","Revere","Worship","Ventilate"],"answer":0,"explanation":"To venerate is to regard with deep respect, so the opposite is to despise. “Revere” and “worship” are synonyms.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-212","question":"In the sentence “Even when the market crashed, the phlegmatic fund manager did not raise his voice”, PHLEGMATIC means:","options":["Excitable and nervous","Sickly and feverish","Unemotional and calm","Fanatical and zealous"],"answer":2,"explanation":"Phlegmatic means having a calm, unexcitable temperament. “Sickly” comes from confusing it with “phlegm”, and “excitable” is the opposite.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-213","question":"One word for “a person who demands strict obedience to rules and discipline”:","options":["Marionette","Martinet","Mentor","Maverick"],"answer":1,"explanation":"A martinet (after a strict 17th-century French drillmaster) is a rigid disciplinarian. A marionette is a puppet, and a maverick is an independent-minded nonconformist.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-214","question":"One word for “a man who readily enters into casual love affairs with women”:","options":["Philanthropist","Philatelist","Misogynist","Philanderer"],"answer":3,"explanation":"A philanderer has many casual affairs. A philanthropist donates to good causes, a philatelist collects stamps, and a misogynist hates women.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-215","question":"One word for “a person who tells anecdotes and stories in a skilful and amusing way”:","options":["Raconteur","Connoisseur","Entrepreneur","Saboteur"],"answer":0,"explanation":"A raconteur is a skilled teller of stories. A connoisseur is an expert judge of taste, and a saboteur deliberately destroys or obstructs.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-216","question":"One word for “something that belongs to a period other than the one in which it is placed”, such as a wristwatch in a film about Akbar:","options":["Anomaly","Antediluvian","Anachronism","Anarchism"],"answer":2,"explanation":"An anachronism (Greek 'ana', against + 'chronos', time) is something out of its proper time. An anomaly is any irregularity, not specifically one of time, and antediluvian simply means very old-fashioned.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-217","question":"In the sentence “Petrol is highly inflammable, so smoking is banned at the pump”, INFLAMMABLE means:","options":["Not able to catch fire","Easily set on fire","Likely to swell","Easily inflated"],"answer":1,"explanation":"“Inflammable” means the same as “flammable”: easily set on fire. The “in-” here is not a negative prefix; the opposite is “non-flammable”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-218","question":"One word for “a person who hates the institution of marriage”:","options":["Misogynist","Misanthrope","Bigamist","Misogamist"],"answer":3,"explanation":"A misogamist (Greek “gamos”, marriage) hates marriage. A misogynist hates women, a misanthrope hates mankind, and a bigamist has two spouses at once.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-219","question":"The idiom “to be at sixes and sevens” means:","options":["To be in confusion and disorder","To be very angry with everyone around","To be unable to count","To be halfway through a task"],"answer":0,"explanation":"Things at sixes and sevens are in a state of total confusion or disarray, as an office might be on the day of a sudden inspection.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-220","question":"The idiom “to be on the horns of a dilemma” means:","options":["To be in serious physical danger","To be under attack from two enemies at once","To face two equally unpleasant choices","To be unable to understand a problem"],"answer":2,"explanation":"The two horns are two choices, both unwelcome; whichever one picks, one gets hurt. It is about a hard decision, not about physical danger.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-221","question":"The idiom “to beard the lion in his den” means:","options":["To flatter a powerful person in order to win favours","To confront the powerful on their own ground","To hunt dangerous animals in their lairs","To grow old and wise like a lion"],"answer":1,"explanation":"To beard (boldly face) the lion in his den is to challenge a powerful person in the place where he is strongest, such as confronting a minister in his own office.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-222","question":"The idiom “to haul someone over the coals” means:","options":["To reprimand someone severely","To torture someone physically","To make someone work very hard","To praise someone excessively"],"answer":0,"explanation":"To haul someone over the coals is to scold them severely for a mistake; the old punishment it refers to is only figurative now.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-223","question":"Fill in the blank with the correct collocation: The cloudburst ___ havoc across three hill districts.","options":["wrecked","ravaged","wreaked","raised"],"answer":2,"explanation":"The fixed collocation is “wreak havoc” (past: wreaked). “Wrecked” and “ravaged” take the damaged place as their object (ravaged three districts), not “havoc”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-224","question":"Fill in the blank: The new rules ___ the sale of tobacco products within 100 metres of a school.","options":["prescribe","subscribe","ascribe","proscribe"],"answer":3,"explanation":"To proscribe is to forbid; to prescribe is to recommend or lay down as a rule. A rule that bans sales near schools proscribes them.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-225","question":"Fill in the blanks: He loves to ___ his wealth, yet he ___ every traffic rule as if the law did not apply to him.","options":["flout; flaunts","flaunt; flouts","flaunt; flaunts","flout; flouts"],"answer":1,"explanation":"To flaunt is to show off (wealth); to flout is to openly disregard (a rule). Swapping the two is one of the commonest usage errors.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-226","question":"Which of the following expressions is an oxymoron?","options":["Busy as a bee","Deafening silence","Time and tide wait for none","Brave as a lion"],"answer":1,"explanation":"An oxymoron joins two contradictory words for effect: silence cannot literally be deafening. 'Busy as a bee' and 'brave as a lion' are similes, and 'time and tide wait for none' is a proverb built on alliteration.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-227","question":"One word for “a person who is between eighty and eighty-nine years old”:","options":["Septuagenarian","Nonagenarian","Octogenarian","Centenarian"],"answer":2,"explanation":"Octo- means eight (as in octagon), so an octogenarian is in his eighties. Septuagenarians are in their seventies, nonagenarians in their nineties, and centenarians are 100 or more.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-228","question":"One word for “passing off another person's writing or ideas as one's own”:","options":["Piracy","Counterfeiting","Perjury","Plagiarism"],"answer":3,"explanation":"Plagiarism is presenting someone else's work as one's own. Piracy is unauthorised copying and selling, counterfeiting is faking money or goods, and perjury is lying under oath.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-229","question":"One word for “a general pardon granted by a government, especially for political offences”:","options":["Amnesty","Amnesia","Clemency","Acquittal"],"answer":0,"explanation":"An amnesty is a general official pardon for a class of offenders. Clemency is mercy shown in an individual case, and an acquittal is a verdict of not guilty.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-230","question":"One word for “a person who loves and collects books, especially rare editions”:","options":["Bibliographer","Librarian","Bibliophile","Lexicographer"],"answer":2,"explanation":"A bibliophile (Greek “biblion”, book + “philos”, loving) loves and collects books. A bibliographer lists books on a subject, and a lexicographer compiles dictionaries.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-231","question":"One word for “the fraudulent misappropriation of money entrusted to one's care”:","options":["Embezzlement","Extortion","Money-laundering","Bribery"],"answer":0,"explanation":"Embezzlement is stealing funds one has been trusted with, as a cashier might. Extortion is obtaining money by threats, money-laundering disguises where illegal money came from, and bribery is offering money to influence someone.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-232","question":"One word for “a fictitious name used by an author in place of the real one”:","options":["Synonym","Anonymous","Patronymic","Pseudonym"],"answer":3,"explanation":"A pseudonym (pen name) is a false name, as “Munshi Premchand” was for Dhanpat Rai. “Anonymous” means without any name, and a patronymic is a name taken from one's father.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-233","question":"Fill in the blank: The editor was formally ___ by the Press Council for publishing unverified allegations.","options":["censored","censured","sensitised","sentenced"],"answer":1,"explanation":"To censure is to criticise or reprimand formally; to censor is to suppress material before or after publication. A press council reprimands, it does not sentence.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-234","question":"Fill in the blank: Having nursed her through a long illness, Ranjit was ___ to leave his ailing mother alone.","options":["loathe","loathed","loathing","loath"],"answer":3,"explanation":"“Loath” (adjective, reluctant) is followed by a to-infinitive: “loath to leave”. “Loathe” is a verb meaning to hate intensely.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-235","question":"Fill in the blanks: The ___ reason for the delay was a shortage of funds, not any ___ objection to the project.","options":["principle; principal","principal; principled","principal; principal","principled; principal"],"answer":1,"explanation":"“Principal” as an adjective means main (the principal reason); an objection based on moral principle is a “principled” objection.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-236","question":"Fill in the blank: From his long silence at the meeting, I ___ that he disagreed with the plan.","options":["implied","implicated","inferred","inflicted"],"answer":2,"explanation":"The listener infers (draws a conclusion); the speaker implies (suggests). Since “I” am drawing the conclusion from his silence, the word is “inferred”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-237","question":"Choose the correctly spelt word: The ___ child hid his sister's books under the bed.","options":["Mischievious","Mischevious","Mischeivous","Mischievous"],"answer":3,"explanation":"The word is “mis-chief-ous”: mischievous, with “ie” and no extra i before “-ous”. “Mischievious” reflects a common mispronunciation.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-238","question":"Choose the correctly spelt word: She was appointed the ___ officer between the two ministries.","options":["Liason","Liasion","Liaison","Laison"],"answer":2,"explanation":"Liaison has an “i” on both sides of the first “a”: l-i-a-i-s-o-n. Dropping the second “i” (liason) is the usual error.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-239","question":"In the sentence “The quarrel over the seating plan was only a storm in a teacup”, the idiom means:","options":["A great fuss over a trivial matter","A serious crisis that threatens everyone","A sudden, violent loss of temper","A secret plot among a few people"],"answer":0,"explanation":"A storm in a teacup is a lot of anger or excitement about something unimportant; the word “only” in the sentence points to its triviality.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-240","question":"The idiom “by fits and starts” means:","options":["Very quickly and without a break","Irregularly, with frequent pauses","Angrily, in sudden fits of temper","Under compulsion from others"],"answer":1,"explanation":"Work done by fits and starts goes on in short bursts with breaks in between, not steadily. It has nothing to do with anger (“fits” of rage).","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-241","question":"The idiom “a feather in one's cap” means:","options":["A mark of disgrace or shame","A meaningless award given to all","An achievement to be proud of","A sign of vanity and showiness"],"answer":2,"explanation":"A feather in one's cap is an honour or achievement one can be proud of, like a young officer cracking a major case.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-242","question":"The idiom “to pay through the nose” means:","options":["To pay in small monthly instalments","To pay a bribe secretly","To pay with great reluctance","To pay an excessively high price"],"answer":3,"explanation":"To pay through the nose is to pay far more than something is worth. Reluctance may go with it, but the idiom is about the excessive price.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-243","question":"The phrase “Achilles' heel” refers to:","options":["A weak or vulnerable point","A strong and firm foundation","A painful injury to the foot","A decisive turning point"],"answer":0,"explanation":"Achilles could be wounded only in his heel, so an Achilles' heel is a single fatal weakness in an otherwise strong person or system.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-244","question":"In the sentence “After the leak was traced to his office, the officer remained under a cloud for months”, the idiom means:","options":["In poor health for a long time","Under suspicion or in disgrace","In a sad and gloomy mood","In hiding from the authorities"],"answer":1,"explanation":"To be under a cloud is to be distrusted or suspected of wrongdoing. The context (a leak traced to his office) points to suspicion, not low spirits.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-245","question":"In the sentence “The proposal to build the flyover has been hanging fire for three years”, the idiom means:","options":["Causing public anger and protest","Being fiercely debated in the council","Remaining undecided and delayed","Running well over its budget"],"answer":2,"explanation":"Something that hangs fire is delayed and remains undecided, like a gun slow to go off. It does not mean causing anger or debate.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-246","question":"The idiom “to keep the wolf from the door” means:","options":["To earn just enough to avoid hunger and want","To protect one's home from thieves and robbers","To avoid unwelcome visitors at the door","To keep one's enemies at a safe distance"],"answer":0,"explanation":"The wolf stands for hunger and want; to keep it from the door is to earn barely enough to survive.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-247","question":"The idiom “to make a clean breast of something” means:","options":["To start afresh","To confess it fully","To clean up a mess","To speak boldly in public"],"answer":1,"explanation":"To make a clean breast of something is to confess everything about it. “Starting afresh” confuses it with “a clean slate”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-248","question":"In the sentence “A cabinet reshuffle is in the offing”, the phrase IN THE OFFING means:","options":["Already cancelled or called off","Kept a closely guarded secret","Likely to happen soon","Long overdue"],"answer":2,"explanation":"“In the offing” (the part of the sea visible from shore) means likely to happen soon. It is often mistaken for “off”, as if something were cancelled.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-vocabulary-249","question":"In the sentence “The smuggler used the young driver as a cat's paw”, the phrase CAT'S PAW means:","options":["A clever thief with a light, silent touch","A spy working for the police","A trusted partner in crime","A person used by another as a tool"],"answer":3,"explanation":"From the fable of the monkey that used a cat's paw to pull chestnuts out of the fire, a cat's paw is a person used by someone else to do risky or dirty work.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-vocabulary-250","question":"The idiom “to play second fiddle” means:","options":["To take a less important role than another","To repeat someone else's ideas as one's own","To act dishonestly behind someone's back","To work only part-time alongside a main job"],"answer":0,"explanation":"To play second fiddle is to be in a subordinate position to someone, as the second violinist is to the leader of an orchestra.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
